def transform(grid):
    out = [row[:] for row in grid]
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    colors = [v for v in counts if v != background]
    if not colors:
        return out
    marker = min(colors, key=lambda v: counts[v])
    fill = 3
    h, w = len(grid), len(grid[0])
    for r in range(h):
        positions = [c for c in range(w) if grid[r][c] == marker]
        if len(positions) >= 2:
            for c in range(min(positions), max(positions) + 1):
                if grid[r][c] == background:
                    out[r][c] = fill
    for c in range(w):
        positions = [r for r in range(h) if grid[r][c] == marker]
        if len(positions) >= 2:
